float AGroveWorld::Height(float X,float Y){
 float Hills=135*FMath::Sin(X/1300.f)*FMath::Sin(Y/1500.f)+70*FMath::Sin(Y/780.f);
 float Mesa=360*FMath::Exp(-FMath::Square((X-2100)/1500.f)-FMath::Square((Y-800)/2200.f));
 return Hills+Mesa;
}
