  if(It->Kind==1){if(Gold<10)return;Gold-=10;Choices++;Health=FMath::Min(100.f,Health+15);}else{S->Shrines++;GainXP(15);Health=FMath::Min(100.f,Health+25);}It->Used=true;Effect(It->GetActorLocation(),2);return;
