    auto Block=[&](FVector Position,FVector Scale){auto* A=GetWorld()->SpawnActor<AStaticMeshActor>(Position,FRotator::ZeroRotator);A->SetReplicates(true);A->GetStaticMeshComponent()->SetStaticMesh(Cube);A->SetActorScale3D(Scale);A->GetStaticMeshComponent()->SetCollisionProfileName(TEXT("BlockAll"));};
    Block(FVector(0,0,-100),FVector(90,90,2));
    Block(FVector(4500,0,250),FVector(1,90,7));Block(FVector(-4500,0,250),FVector(1,90,7));
    Block(FVector(0,4500,250),FVector(90,1,7));Block(FVector(0,-4500,250),FVector(90,1,7));
